console.log("TMqttClient.ts");
class TMqttClient {
  client;
  url;
  options;
  constructor(url, options = {}) {
    this.url = url;
    this.options = {
      clientId: `tmqtt_${Math.random().toString(16).slice(2, 8)}`,
      keepalive: 60,
      reconnectPeriod: 1e3,
      ...options
    };
    this.client = mqtt.connect(this.url, this.options);
    this.registerEvents();
  }
  registerEvents() {
    this.client.on("connect", () => {
    });
    this.client.on("error", (err) => {
      console.error("❌ MQTT connection error:", err.message);
    });
    this.client.on("reconnect", () => {
    });
    this.client.on("close", () => {
    });
  }
  subscribe(topic) {
    this.client.subscribe(topic, (err) => {
      if (err) {
        console.error(`❌ Failed to subscribe to topic "${topic}":`, err.message);
      }
    });
  }
  publish(topic, message) {
    this.client.publish(topic, message, {}, (err) => {
      if (err) {
        console.error(`❌ Failed to publish to "${topic}":`, err.message);
      }
    });
  }
  onMessage(callback) {
    this.client.on("message", (topic, message) => {
      callback(topic, message);
    });
  }
  disconnect() {
    this.client.end(() => {
    });
  }
}

class QEngine extends QLooper {
  graphics;
  _isPhysicsEnabled = true;
  _isPhysicsDebugEnabled = true;
  mqttClient;
  constructor() {
    super();
    const topic = GlobalConfig.topic.scene3d;
    this.mqttClient = new TMqttClient(GlobalConfig.getWsBrokerUrl());
    this.mqttClient.subscribe(topic);
    this.mqttClient.onMessage((topic2, message) => {
      if (topic2 !== topic2) return;
      const json = JSON.parse(message.toString());
      if (!json || json.action !== "exposure") return;
      const { exposure } = json;
      if (!exposure) return;
      const { value = 1, duration = 2e3 } = exposure;
      console.log(`🌞 Set exposure to ${value} over ${duration}ms`);
      this.graphics.getRenderer().fadeExposure(value, duration);
    });
  }
  /**
   * Helper functions
   */
  getGraphics = () => this.graphics;
  getCamera = () => this.graphics.getCamera();
  getScene = () => this.graphics.getScene();
  getRenderer = () => this.graphics.getRenderer();
  getOrbitControls = () => this.graphics.getOrbitControls();
  getCanvas = () => this.graphics.getCanvas();
  async init() {
    this.graphics = new QGraphics();
    await this.graphics.init();
    this.onFrame(() => this.update());
    this.start();
    return this;
  }
  update() {
    const g = this.graphics;
    g.getRenderer().render(g.getScene(), g.getCamera());
    g.getOrbitControls().update();
    g.getCssRenderer().render(g.getCssScene(), g.getCamera());
  }
  setPhysicsEnabled(enabled) {
    this._isPhysicsEnabled = enabled;
    return this;
  }
  getPhysicsEnabled() {
    return this._isPhysicsEnabled;
  }
  setPhysicsDebugEnabled(enabled) {
    this._isPhysicsDebugEnabled = enabled;
    return this;
  }
  getPhysicsDebugEnabled() {
    return this._isPhysicsDebugEnabled;
  }
  isPhysicsEnabled() {
    return this._isPhysicsEnabled;
  }
  isPhysicsDebugEnabled() {
    return this._isPhysicsDebugEnabled;
  }
}

