const main = () => {
  let MODELS = [`models/e84/psoc_e84.gltf`];
  new QEngine().init().then((engine) => {
    console.log(`Engine initialized.`);
    const graphics = engine.getGraphics();
    const chrome = new QChromeMemory(engine);
    graphics.loadModels(MODELS).then(async (gltfs) => {
      let e84;
      gltfs.forEach((gltf) => {
        console.log(gltf.scene.name);
        if (gltf.scene.name === "E84") {
          e84 = gltf;
        }
        if (gltf.scene.name === "drone") ;
      });
      cubeMapLoader(`Yokohama3`).then((texture) => {
        graphics.getScene().background = texture;
        graphics.getScene().environment = texture;
      });
      const leds = [];
      setTimeout(() => {
        _LED_NAMES.forEach((name, index) => {
          const led = new E84Led(engine, index, 0.5);
          leds.push(led);
        });
        setInterval(() => {
          leds.forEach((led, index) => {
            led.fadeIntensity(1e3);
          });
        }, 1e3);
      }, 500);
      setTimeout(() => {
        const board = new E84Pcb(engine, e84);
        board.defaultView(1e3);
        new QTransformControls(engine, engine.getScene().getObjectByName("E84"));
      }, 1e3);
      new E84PswController(engine);
      new InfoCard(engine, engine.getGraphics().getObjectByName("SW1"));
      engine.onFrame((params) => {
        if (params.frames % 30 == 0) {
          chrome.update(engine);
        }
      });
    });
  });
};
main();
